import { Component } from '@angular/core';
import { HeaderService } from '../../../core/services/header/header.service';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { NotificationsService } from '../../../shared/services/notifications.service';
import { CommonModule } from '@angular/common';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { NotificationsComponent } from '../../../shared/components/notifications/notifications.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';

@Component({
  selector: 'app-present-header',
  standalone: true,
  imports: [IconComponent, ProfileComponent, MatMenuModule, MatTooltipModule, ButtonComponent],
  templateUrl: './present-header.component.html',
  styleUrl: './present-header.component.scss'
})
export class PresentHeaderComponent {

  nCaseid: string;

  flag: boolean = false;

  constructor(public hs: HeaderService, public ss: SecureStorageService, public NotificationS: NotificationsService, private cm: CommonfunctionService) {
  }

  async ngOnInit() {
    this.hs.userdetail = await this.ss.getUserInfo();
  }

  goToHome() {
    this.nCaseid = this.hs.getCaseid();

    if (!this.nCaseid) {
      return;
    }
    
    this.cm.gotoUrl('/present/home', { id: this.nCaseid });
  }

  newTab(){
    window.open(location.href, '_blank');
  }

  showHomeBtn() {
    return !(['home', 'subtype'].some(v => location.pathname.includes(v)))
  }
}
