import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, UrlTree, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { AuthValidationService } from '../services/auth-validation/auth-validation.service';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {

  constructor(
    private router: Router,
    private authValidation: AuthValidationService
  ) { }

  canActivate(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): Observable<boolean | UrlTree> | Promise<boolean | UrlTree> | boolean | UrlTree {
    return this.checkLogin();
  }

  private async checkLogin(): Promise<boolean> {
    const result = await this.authValidation.validate();

    if (!result.isValid) {
      this.router.navigate(['/auth/login']);
      return false;
    }
    return true;
  }

}

@Injectable({
  providedIn: 'root'
})
export class LogedGuard implements CanActivate {

  constructor(
    private router: Router,
    private authValidation: AuthValidationService
  ) { }

  canActivate(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): Observable<boolean | UrlTree> | Promise<boolean | UrlTree> | boolean | UrlTree {
    return this.checkLogin();
  }

  private async checkLogin(): Promise<boolean> {
    const result = await this.authValidation.validate();

    if (result.isValid) {
      this.router.navigate(['/user/dashboard']);
      return false;
    }
    return true;
  }

}
