import { Component } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { InputComponent } from '../../../shared/components/input/input.component'; 
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { SessionService } from '../../services';
import { HttpClientModule } from '@angular/common/http';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { FormsModule } from '@angular/forms';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatCheckboxModule } from '@angular/material/checkbox';
@Component({
  selector: 'app-realtimesetting',
  standalone: true,
  providers: [SessionService],
  imports: [ButtonComponent, FormsModule, MatTooltipModule, MatCheckboxModule, CommonModule, ReactiveFormsModule, HttpClientModule, TranslateModule, MatFormFieldModule, MatSelectModule],
  templateUrl: './realtimesetting.component.html',
  styleUrl: './realtimesetting.component.scss'
})
export class RealtimesettingComponent {
  modes: any = [];
  frm: FormGroup;
  localServer: any = {};
  protocols: any[] = [];
  isReconnecting: boolean;
  constructor(private formBuilder: FormBuilder, public sessionService: SessionService, private dialog: MatDialog, private translate: TranslateService) {
    this.frm = this.formBuilder.group({
      mode: ['T', [Validators.required]],
      ip: ['', [Validators.required]],
      port: ['', [Validators.required]],
      // protocol: ['C', [Validators.required]],
      cUnicuserid: [sessionService.cUnicuserid]
    });

    this.modes = [
      {
        type: 'T',
        name: this.translate.instant('rt.realtimeSetting.modes.liveDataTcpIp')
      }
    ];
    this.protocols = [
      { name: this.translate.instant('rt.realtimeSetting.protocols.caseView'), value: 'C' },
      { name: this.translate.instant('rt.realtimeSetting.protocols.bridgeView'), value: 'B' }
    ];

    this.serverDetail();
  }
  async serverDetail() {
    let data = await this.sessionService.fetchLocalServer();
    if (data) {
      this.localServer = data
      this.frm.patchValue(
        {
          mode: this.localServer.mode,
          ip: this.localServer.ip,
          port: this.localServer.port,
          cUnicuserid: this.localServer.cUnicuserid
        }
      );
    }
  }
  async submit(isReconnect?): Promise<void> {
    if (this.frm.invalid) {
      this.sessionService.show(this.translate.instant('rt.realtimeSetting.invalidForm'))
      return;
    }

    
    const res = await this.sessionService.saveLocalServer(this.frm.value)
    if (!isReconnect) {
      this.sessionService.show(res["value"])
      this.dialog.closeAll();
    }

  }

  async retry() {
    if (this.isReconnecting)
      return;
    this.isReconnecting = true;
    await this.submit(true);
    setTimeout(() => {
      this.isReconnecting = false;
    }, 200);
  }

  trackByMode(index: number, item: any): any {
    return item.type;
  }


}
