import { ChangeDetectorRef, Component, OnDestroy, OnInit } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { HeaderService } from '../../../core/services/header/header.service';
import { CommunicationService } from '../../services/communication/communication.service';
import { TranslateService } from '@ngx-translate/core';
import { LanguageService } from '../../../core/services/language/language.service';
import { SidenavItem } from '../../interfaces/sidenav.interface';
import { SocketService } from '../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-sidenav',
  standalone: true,
  imports: [IconComponent, MatMenuModule, CommonModule],
  templateUrl: './sidenav.component.html',
  styleUrl: './sidenav.component.scss'
})
export class SidenavComponent implements OnInit, OnDestroy {
  expandnav: boolean = false;
  isHovered: boolean = false;
  expandNavTimeout: ReturnType<typeof setTimeout> | null = null;
  sidelist: SidenavItem[] = [];

  /** Tracks server-pushed session-status changes so the RT badge flips
   *  Live ↔ idle without the user having to re-enter the case. Backend
   *  emits via `on-notification` (apps/realtime-server/src/services/session/
   *  session.service.ts:218,sessionStart) with cStatus 'R' (Running) or
   *  'E' (Ended). */
  private notificationSub?: Subscription;

  constructor(private readonly cf: CommonfunctionService, private readonly hs: HeaderService, private readonly cs: CommunicationService,
    private readonly router: Router, private readonly translate: TranslateService, private readonly languageService: LanguageService,
    private readonly socket: SocketService, private readonly cdr: ChangeDetectorRef
  ) {
  }

  ngOnInit(): void {
    this.loadSidelistFromTranslation();

    this.notificationSub = this.socket.getNotification().subscribe((res: any) => {
      const payload = res?.data?.data ?? res?.data ?? res ?? {};
      const status = payload?.cStatus;
      if (status !== 'R' && status !== 'E') return;

      // Only react when the event belongs to the case the user is currently
      // looking at. nCaseid match is the primary gate; if the backend didn't
      // send nCaseid we fall back to the nSesid the user already had open.
      const currentCaseId = this.hs?.Casedetail?.nCaseid;
      if (!currentCaseId) return;

      const eventCaseId = payload?.nCaseid != null ? String(payload.nCaseid) : '';
      const eventSesId = payload?.nSesid != null ? String(payload.nSesid) : '';
      const matches = eventCaseId
        ? String(currentCaseId) === eventCaseId
        : (!!this.hs.Casedetail?.nSesid && String(this.hs.Casedetail.nSesid) === eventSesId);
      if (!matches) return;

      // CaseDetailResponce.nSesid is typed as number but the live system
      // stores UUID strings — cast through any to avoid widening the
      // interface for one local mutation.
      const detail = this.hs.Casedetail as any;
      if (status === 'R' && eventSesId) {
        detail.nSesid = eventSesId;
      } else if (status === 'E') {
        detail.nSesid = null;
      }
      this.cdr.detectChanges();
    });
  }

  ngOnDestroy(): void {
    this.notificationSub?.unsubscribe();
  }

  private loadSidelistFromTranslation(): void {
    this.translate.get('SIDENAV').subscribe(
      (sidenavData: any) => {
        if (!sidenavData || typeof sidenavData !== 'object' || !sidenavData.EVIDENCE) {
          return;
        }

        this.sidelist = [
          { ...sidenavData.EVIDENCE, hidden: false, selected: false },
          { ...sidenavData.FACT_WORKSPACE, hidden: false, selected: false },
          { ...sidenavData.CONTACT, hidden: false, selected: false },
          { ...sidenavData.TASKS, hidden: false, selected: false },
          { ...sidenavData.EXPORT, hidden: false, selected: false },
          { ...sidenavData.DOWNLOAD, hidden: false, selected: false },
          { ...sidenavData.REALTIME, hidden: false, selected: false }
        ];
        // Set selected state based on current page
        for (const item of this.sidelist) {
          item.selected = this.ispage(item.component);
        }
      }
    );
  }

  trackByIndex(index: number): number {
    return index;
  }

  rtwindow: Window | null = null;
  selectOption(x: SidenavItem): void {
    // RT button only acts as a live-session entry point. When no session is
    // running we keep the button visible (so users learn it exists) but block
    // navigation — the hover tooltip explains where to find published
    // transcripts instead.
    if (this.isItemDisabled(x)) return;

    // Mark the clicked item as selected
    x.selected = true;

    // Unselect other items
    this.sidelist.filter(y => y !== x).forEach(y => y.selected = false);

    // Navigate to the corresponding route
    if (x.component === "rt-realtime/feed") {
      const nCaseid = this.hs.Casedetail?.nCaseid || this.hs.nCaseid;
      const url = this.router.serializeUrl(
        this.router.createUrlTree(['/rt-realtime/feed', btoa(JSON.stringify({ nSesid: this.hs?.Casedetail?.nSesid || 0, nCaseid: this.hs.Casedetail?.nCaseid || this.hs.nCaseid }))])
      );
      if (this.rtwindow && !this.rtwindow.closed) {
        this.rtwindow.focus();
      } else {
        this.rtwindow = window.open(url, nCaseid);
      }
    } else if (x.component === "realtime/feed") {
      const nCaseid = this.hs.Casedetail?.nCaseid || this.hs.nCaseid;
      const url = this.router.serializeUrl(
        this.router.createUrlTree(['/realtime/feed', btoa(JSON.stringify({ nSesid: this.hs?.Casedetail?.nSesid || 0, nCaseid: this.hs.Casedetail?.nCaseid || this.hs.nCaseid }))])
      );
      if (this.rtwindow && !this.rtwindow.closed) {
        this.rtwindow.focus();
      } else {
        this.rtwindow = window.open(url, nCaseid);
      }
    } else if (x.component === "rt/dashboard") {
      const nCaseid = this.hs.Casedetail?.nCaseid || this.hs.nCaseid;
      const url = this.router.serializeUrl(
        this.router.createUrlTree(['/realtime/dashboard', btoa(JSON.stringify({ nSesid: this.hs?.Casedetail?.nSesid || 0, nCaseid: this.hs.Casedetail?.nCaseid || this.hs.nCaseid }))])
      );
      if (this.rtwindow && !this.rtwindow.closed) {
        this.rtwindow.focus();
      } else {
        this.rtwindow = window.open(url, nCaseid);
      }
    } else {
      this.cf.goto(x.component, { id: this.hs.Casedetail?.nCaseid || this.hs.nCaseid });
    }

    // Toggle sidebar expansion state
    if (this.expandnav) {
      // Close the sidebar if it's already expanded
      this.expandnav = false;
    } else {
      // Expand the sidebar if not already expanded
      this.expandnav = true;

      // Clear any existing timeout to ensure the sidebar stays expanded
      if (this.expandNavTimeout) {
        clearTimeout(this.expandNavTimeout);
      }
    }
  }

  mouseleave(): void {
    if (this.expandNavTimeout) {
      clearTimeout(this.expandNavTimeout);
    }

    this.expandNavTimeout = setTimeout(() => {
      this.expandnav = false;
    }, 1000);
  }

  mouseover(): void {
    this.isHovered = true;
    if (this.expandNavTimeout) {
      clearTimeout(this.expandNavTimeout);
    }
  }

  ispage(flag: string): boolean {
    return globalThis.location.href.includes(flag);
  }

  isSessionLive(): boolean {
    return !!this.hs?.Casedetail?.nSesid;
  }

  /** RT entry is disabled until a live session is active. */
  isItemDisabled(item: SidenavItem): boolean {
    return item.cType === 'RT' && !this.isSessionLive();
  }
}
