import { CommonModule, Location } from '@angular/common';
import { Component } from '@angular/core';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';
import { SecureStorageService } from '../../services/storage/secure-storage.service';
import { HeaderService } from '../../services/header/header.service';
import { SearchComponent } from '../../../shared/components/search/search.component';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { CommonfunctionService } from '../../utility/commonfunction.service';
import { CaseBuilderService } from '../../../adminpanel/services/case-builder/case-builder.service';

@Component({
  selector: 'app-adminheader',
  standalone: true,
  imports: [CommonModule, IconComponent, MatMenuModule, ProfileComponent, SearchComponent, ButtonComponent],
  templateUrl: './adminheader.component.html',
  styleUrl: './adminheader.component.scss'
})
export class AdminheaderComponent {
  expandhyper: boolean = false;
  casedetal: any = {};
  currentadminpath: string = 'Case Detail';
  constructor(public ss: SecureStorageService, private location: Location, public hs: HeaderService, private cs: CommunicationService,
    private cf: CommonfunctionService,
    private caseBuilderService:CaseBuilderService
  ) {

  }

  async ngOnInit() {
    this.hs.userdetail = await this.ss.getUserInfo();

  }

  goBack() {
    this.location.back();
  }

  goToUserPermission() {
    this.cs.callFunction("USER-PERMISSION");
  }

  goToRolePermission() {
    this.cs.callFunction("ROLE-PERMISSION");
  }



  deleteCase() {
    this.cs.callFunction("DELETE-CASE");
  }



  viewTickets() {
    this.cs.callFunction("VIEW-TICKETS");
  }

  gohome() {
    this.hs.goAdminHome();
  }


  StartHyperlink(mode: 'T' | 'E', type: 'K' | 'R', isDeep?: boolean) {
    this.cs.callFunction({ event: 'START-HYPERLINK', mode: mode, cKeeptype: type, nBundledetailid: null, isDeep: isDeep });
  }

  caseactivity() {
    debugger
    this.cf.goto('case-activity', { id: this.hs.Casedetail.nCaseid })
  }

  realtimeactivity() {
    this.cf.goto('realtime-activity', { id: this.hs.Casedetail.nCaseid })
  }

  updateCaseTuples() {
    debugger;
    if (this.hs?.Casedetail?.nCaseid)
    this.caseBuilderService.updateCaseTuples(this.hs?.Casedetail?.nCaseid);
  }

}






