import { HelpcenterComponent } from './shared/components/helpcenter/helpcenter.component';
import { Routes } from '@angular/router';
import { AuthGuard, LogedGuard } from './core/guard/auth.guard';
import { CaseActivityComponent } from './adminpanel/components/activity-log/case-activity/case-activity.component';
import { PermissionGuard } from './core/guard/permission/permission.guard';

export const routes: Routes = [

  { path: '', redirectTo: 'auth', pathMatch: 'full' },
  {
    path: 'auth',
    loadChildren: () => import('./core/core.module').then(m => m.CoreModule),
    canActivate: [LogedGuard]
  },
  {
    path: 'user',
    loadChildren: () => import('./userpanel/modules/userdashboard/userdashboard.module').then(m => m.userdashboardModule),
    canActivate: [AuthGuard],
    // data: { preload: true }
  },
  {
    path: 'admin',
    loadChildren: () => import('./adminpanel/modules/admindashboard/admindashboard.module').then(m => m.AdmindashboardModule),
    canActivate: [AuthGuard]
  },
  {
    path: 'casebuilder',
    loadChildren: () => import('./adminpanel/modules/casebuilder/casebuilder.module').then(m => m.CasebuilderModule),
    canActivate: [AuthGuard]
  },
  {
    path: 'permission',
    loadChildren: () => import('./adminpanel/modules/permission/permission.module').then(m => m.PermissionModule),
    canActivate: [AuthGuard]
  },
  {
    path: 'managefiles',
    loadChildren: () => import('./adminpanel/modules/bundlemanagement/bundlemanagement.module').then(m => m.BundlemanagementModule),
    canActivate: [AuthGuard]
  },
  {
    path: 'myfiles',
    loadChildren: () => import('./userpanel/modules/myfiles/myfiles.module').then(m => m.MyfilesModule),
    canActivate: [AuthGuard]
  },
  /*
  {
    path: 'realtime',
    loadChildren: () => import('./realtime/modules/realtime/realtime.module').then(m => m.RealtimeModule),
    data: { permission: 'RT' },
    canActivate: [AuthGuard],
    canActivateChild: [PermissionGuard],
  },
*/
  {
    path: 'realtime',
    loadChildren: () => import('./rt/modules/rt/rt.module').then(m => m.RtModule),
    canActivate: [AuthGuard],
    data: { permission: 'RT' },
    canActivateChild: [PermissionGuard],
  },
  {
    path: 'upload',
    loadChildren: () => import('./adminpanel/modules/uploadmanager/uploadmanager.module').then(m => m.UploadmanagerModule),
    data: { permission: 'UM' },
    canActivate: [AuthGuard],
    canActivateChild: [PermissionGuard],
  },
  {
    path: 'individual',
    loadChildren: () => import('./userpanel/modules/individual/individual.module').then(m => m.IndividualModule),
    canActivate: [AuthGuard],
    // data: { preload: true }
  },
  {
    path: 'viewer',
    loadChildren: () => import('./pdf/modules/pdf/pdf.module').then(m => m.PdfModule),
    canActivate: [AuthGuard],
    // data: { preload: true }
  },
  {
    path: 'present',
    loadChildren: () => import('./presentation/modules/present/present.module').then(m => m.PresentModule),
    data: { permission: 'PT' },
    canActivate: [AuthGuard],
    canActivateChild: [PermissionGuard],
    // data: { preload: true }
  },
  // {
  //   path: 'present',
  //   loadChildren: () => import('./userpanel/components/present/home/home.component').then(m => m.HomeComponent),
  //   canActivate: [AuthGuard]
  // },
  {
    path: 'userguide/:id',
    loadComponent: () => import('././shared/components/userguide/userguide.component').then(m => m.UserguideComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'helpcenter',
    loadComponent: () => import('././shared/components/helpcenter/helpcenter.component').then(m => m.HelpcenterComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'helpcenterdetail/:id',
    loadComponent: () => import('././shared/components/helpcenter/helpcenterdetail/helpcenterdetail.component').then(m => m.HelpcenterdetailComponent),
    canActivate: [AuthGuard]
  },

  // {
  //   path: 'realtimelog/:id',
  //   loadComponent: () => import('././realtime/components/realtimelog/realtimelog.component').then(m => m.RealtimelogComponent),
  //   canActivate: [AuthGuard]
  // },

  {
    path: 'backend-process',
    loadComponent: () => import('././adminpanel/components/back-proc-dash/back-proc-dash.component').then(m => m.BackProcDashComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'case-activity/:id',
    loadComponent: () => import('./adminpanel/components/activity-log/case-activity/case-activity.component').then(m => m.CaseActivityComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'realtime-activity/:id',
    loadComponent: () => import('./adminpanel/components/activity-log/realtimeactivity/realtimeactivity.component').then(m => m.RealtimeactivityComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'helpcenteradmin',
    loadComponent: () => import('./adminpanel/components/helpcenter/helpcenteradmin/helpcenteradmin.component').then(m => m.HelpcenteradminComponent),
    canActivate: [AuthGuard]
  }, {
    path: 'transcript',
    loadChildren: () => import('./adminpanel/modules/transcript/transcript.module').then(m => m.TranscriptModule),
    canActivate: [AuthGuard],
    // data: { preload: true }
  },
  {
    path: 'quickview/:id',
    loadComponent: () => import('./userpanel/components/quickpdf/quickpdf.component').then(m => m.QuickpdfComponent),
    canActivate: [AuthGuard]
  }, { path: 'ocrlist', loadComponent: () => import('./adminpanel/components/upload/ocrlist/ocrlist.component').then(m => m.OcrlistComponent), canActivate: [AuthGuard] },
];
