import { Component } from '@angular/core';
import { HeaderService } from '../../services/header/header.service';
import { SecureStorageService } from '../../services/storage/secure-storage.service';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';

@Component({
  selector: 'app-uploadheader',
  standalone: true,
  imports: [ProfileComponent],
  templateUrl: './uploadheader.component.html',
  styleUrl: './uploadheader.component.scss'
})
export class UploadheaderComponent {

  constructor(private ss: SecureStorageService, public hs: HeaderService,) {}



  async ngOnInit() {
    this.hs.userdetail = await this.ss.getUserInfo();

  }

}
