import { Component, HostListener, OnInit, AfterViewInit, OnDestroy, inject } from '@angular/core';
import { Router, RouterOutlet } from '@angular/router';
import { CommonfunctionService } from './core/utility/commonfunction.service';
import { CommunicationService } from './shared/services/communication/communication.service';
import { FcmnotificationService } from './core/services/fcm/fcmnotification.service';
import { AdminheaderComponent } from './core/headercomponents/adminheader/adminheader.component';
import { CommonModule } from '@angular/common';
import { NetworkStatusService } from './shared/services/network-status/network-status.service';
import { Observable, distinctUntilChanged, scan, switchMap, timer, of, map, startWith, tap } from 'rxjs';
import { UploadheaderComponent } from './core/headercomponents/uploadheader/uploadheader.component';
import { SecureStorageService } from './core/services/storage/secure-storage.service';
import { MULTI_DEVICE_SESSION_KEY } from './core/utility/commonfunction.service';
import { AuthValidationService } from './core/services/auth-validation/auth-validation.service';
import { SocketService } from './core/services/socket/socket.service';
import { HeaderComponent } from './core/headercomponents/header/header.component';
import { MainheaderComponent } from './core/headercomponents/mainheader/mainheader.component';
import { SidenavComponent } from './shared/components/sidenav/sidenav.component';
import { environment } from '../environments/environment';
import { PresentHeaderComponent } from "./presentation/components/present-header/present-header.component";
import { BroadcastingService } from './core/services/broadcasting/broadcasting.service';
import { broadCastBody } from './core/interfaces/login.interface';
import { UserNotificationComponent } from './shared/components/user-notification/user-notification.component';
import { RealtimeheaderComponent } from './rt/components/feeds/realtimeheader/realtimeheader.component';
import { SessionService } from './rt/services/session/session.service';
import { ErrorHandlerUtil } from './userpanel/utility/error-handler.util';
import { HeaderService } from './core/services/header/header.service';
import { RealtimeFacade } from './rt/facades/realtime.facade';
import { MatDialog } from '@angular/material/dialog';
import { AssignserversComponent } from './rt/components/assignservers/assignservers.component';
import { RealtimesettingComponent } from './rt/components/realtimesetting/realtimesetting.component';

import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, AdminheaderComponent, CommonModule, UploadheaderComponent, HeaderComponent, MainheaderComponent, SidenavComponent, PresentHeaderComponent, RealtimeheaderComponent],
  templateUrl: './app.component.html',
  styleUrl: './app.component.scss'
})
export class AppComponent implements OnInit, AfterViewInit, OnDestroy {

  @HostListener('document:contextmenu', ['$event'])
  onRightClick(event: MouseEvent) {
    const restrictedPaths = ['/viewer/', '/individual/'];
    const currentUrl = this.router.url;
    const isRestricted = restrictedPaths.some(path => currentUrl.includes(path));
    if (isRestricted) {
      event.preventDefault();
    }
  }
  title = 'etabella';
  mode: string = environment.name || "" // 'production' || 'development' || 'staging' || 'testing' || 'local'

  public rtFacade = inject(RealtimeFacade);
  private dialog = inject(MatDialog);
  private authValidation = inject(AuthValidationService);
  private cm = inject(CommonfunctionService);
  private cs = inject(CommunicationService);
  private networkStatus = inject(NetworkStatusService);
  private onVisibilityChange = this.handleVisibilityChange.bind(this);
  private onWindowMessage = this.handleWindowMessage.bind(this);

  /** Connection-status toast state for the bottom-of-app indicator.
   *  - 'lost': dark toast w/ slashed-wifi icon, persists while
   *    NetworkStatusService.isOnline$ reports false.
   *  - 'restored': dark toast w/ green wifi icon, shown for 3s right
   *    after network comes back, then auto-dismisses.
   *  - 'ok': hidden — normal operation.
   *
   *  Distinct from the SocketService realtime-reconnect Subject (which
   *  drives feed re-fetch) because that fires on transient socket-level
   *  reconnects too — those don't always coincide with a real network
   *  drop. This toast is gated on the browser's actual online/offline
   *  state plus an HTTP connectivity probe, so it only appears when the
   *  user has genuinely lost connectivity. */
  connectionBanner$: Observable<'lost' | 'restored' | 'ok'> = this.networkStatus.isOnline$.pipe(
    distinctUntilChanged(),
    // scan tracks the previous online state so we can distinguish "started
    // online" (stay 'ok', no toast) from "came back online" (show
    // 'restored' for 3s).
    scan<boolean, { online: boolean; wasOffline: boolean }>(
      (acc, online) => ({
        online,
        wasOffline: !online || (acc.online === false && online === true ? true : acc.wasOffline),
      }),
      { online: true, wasOffline: false }
    ),
    switchMap(state => {
      if (!state.online) return of<'lost' | 'restored' | 'ok'>('lost');
      if (state.wasOffline) {
        // Show 'restored' immediately, then auto-dismiss to 'ok' after 3s.
        // Implemented as `timer(3000) → 'ok'` with `startWith('restored')`
        // because the previous `timer(0, 3000) + scan(tick+1, 0)` started
        // emitting at tick=1 (seed is 0, first emission is 0+1) — so
        // `tick === 0 ? 'restored' : 'ok'` was always 'ok' and the green
        // toast never appeared. startWith guarantees the first synchronous
        // emission is 'restored', then timer fires once at +3000ms with 'ok'.
        return timer(3000).pipe(
          map(() => 'ok' as 'lost' | 'restored' | 'ok'),
          startWith('restored' as 'lost' | 'restored' | 'ok')
        );
      }
      return of<'lost' | 'restored' | 'ok'>('ok');
    }),
    // Clear any stale dismiss flag when the banner state transitions.
    // Without this, dismissing the offline toast would also suppress the
    // 'lost' toast on the NEXT offline cycle (dismissedBannerState would
    // still equal 'lost' from last time). The template's *ngIf gate
    // (dismissedBannerState !== bannerState) plus this tap means dismiss
    // only suppresses the in-flight state, not future ones.
    tap(newState => {
      if (this.dismissedBannerState && this.dismissedBannerState !== newState) {
        this.dismissedBannerState = null;
      }
    })
  );

  /** Per-state dismiss flag. Click-to-X on the toast sets this so the
   *  toast hides immediately without waiting for the network state to
   *  change. Resets whenever the banner state transitions (so dismissing
   *  the offline toast doesn't suppress the green "restored" toast that
   *  fires when the network comes back). */
  dismissedBannerState: 'lost' | 'restored' | 'ok' | null = null;

  /** Click handler for the toast's "Refresh" link. Triggers a hard reload
   *  so the user's offending tab gets a clean state — common ask after a
   *  long disconnect when caches/SPA state could be stale. */
  reloadPage(): void {
    window.location.reload();
  }

  /** Click handler for the toast's X-close button. Marks the current
   *  banner state as dismissed; the toast hides until the next state
   *  transition reassigns it. */
  dismissBanner(state: 'lost' | 'restored' | 'ok'): void {
    this.dismissedBannerState = state;
  }

  constructor(private readonly fcm: FcmnotificationService, private readonly storage: SecureStorageService,
    public readonly socket: SocketService, private readonly broadCastService: BroadcastingService, private readonly router: Router, private readonly session: SessionService, private readonly hs: HeaderService, private translate: TranslateService) {
    // Set default language
    this.translate.setDefaultLang('en');
    this.translate.use('en');
  }
  ngOnInit() {
    this.hs.init();
    this.broadCastService.authListener().subscribe((body: broadCastBody) => {
      if (body.event === 'LOGED-OUT') {
        this.authValidation.clearCache();
        this.router.navigate(['/auth/login']);
      } else if (body.event === 'LOGIN') {
        this.authValidation.clearCache();
        this.router.navigate(['/user/dashboard']);
      } else if (body.event === 'LOG-IN-ANOTHER-BROWESER') {
        if (localStorage.getItem(MULTI_DEVICE_SESSION_KEY) === 'true') {
          return;
        }
        this.authValidation.clearCache();
        localStorage.setItem('force_logout', 'true');
        this.storage.logOut();
        this.router.navigate(['/auth/login']);
      }
    });
    document.addEventListener('visibilitychange', this.onVisibilityChange);
    window.addEventListener('message', this.onWindowMessage);
  }

  ngOnDestroy() {
    document.removeEventListener('visibilitychange', this.onVisibilityChange);
    window.removeEventListener('message', this.onWindowMessage);
  }

  /** Cross-window bridge from the realtime popup window. When the user
   *  clicks "Open Evidence Transcript Folder" in the session-closed modal
   *  (realtime-shell.component.ts → openTranscriptFolder), the RT window
   *  postMessages here and self-closes. We focus this Hearing Hub window
   *  and route to /myfiles/filesaction/<nCaseid> so the user lands in
   *  Evidence with the right case loaded. */
  private handleWindowMessage(event: MessageEvent): void {
    if (event.origin !== window.location.origin) return;
    const data = event.data;
    if (!data || typeof data !== 'object') return;
    if (data.event !== 'OPEN-TRANSCRIPT-FOLDER') return;
    const nCaseid = data.nCaseid;
    if (!nCaseid) return;
    try { window.focus(); } catch {}

    // Same already-on-page check that notifications.component.ts uses for
    // SHOW-UPLOAD: skip the navigation if we're already in Evidence (and on
    // the same case), otherwise navigate then trigger after a tick so the
    // SectionComponent has time to subscribe to functionCalled$.
    const alreadyInEvidence = window.location.href.includes('/myfiles/filesaction');
    if (alreadyInEvidence) {
      this.cs.callFunction({ type: 'CHANGE-SECTION', cFoldertype: 'TS' });
      return;
    }
    this.cm.goto('/myfiles/filesaction', { id: nCaseid });
    setTimeout(() => {
      this.cs.callFunction({ type: 'CHANGE-SECTION', cFoldertype: 'TS' });
    }, 50);
  }

  private async handleVisibilityChange() {
    if (document.visibilityState !== 'visible') return;
    // Skip check on auth pages (user is not logged in)
    if (this.router.url.startsWith('/auth')) return;

    this.authValidation.clearCache();

    // Retry validation up to 2 times to handle transient network failures (e.g., during deployment)
    let retries = 2;
    let result = await this.authValidation.validate();
    while (!result.isValid && retries > 0) {
      await new Promise(r => setTimeout(r, 2000));
      this.authValidation.clearCache();
      result = await this.authValidation.validate();
      retries--;
    }

    if (!result.isValid) {
      this.storage.logOut();
      this.router.navigate(['/auth/login']);
      return;
    }

    // Socket health-check on tab return.
    //
    // Browsers throttle JS timers in background tabs to ~1Hz, which is
    // too slow for Socket.IO's default 25s ping interval to keep up with
    // load-balancer / firewall idle-timeouts (commonly 60s). After 20-30
    // min of idle the underlying TCP socket is usually dead, but the
    // socket.io client doesn't know yet — the next user click then trips
    // over the dead socket and appears to "freeze" while reconnect
    // attempts churn.
    //
    // Proactively forcing a reconnect HERE (the moment the tab becomes
    // visible) pays the recovery cost up-front: by the time the user
    // moves their mouse to click anything, the socket is either healthy
    // or actively reconnecting with the rejoin-rooms logic from
    // socket.service.ts already running. Combined with the realtimeRooms
    // auto-rejoin and the realtime-reconnect refetch in feed-display,
    // this closes the "frozen-after-idle" gap end-to-end.
    try {
      // Main app socket (notifications, uploads, presentation, etc.).
      // .connect() is a no-op when already connected, so safe to call
      // unconditionally.
      if (this.socket.socket && !this.socket.socket.connected) {
        this.socket.socket.connect();
      }
      // Realtime socket (live feed). Force a clean cycle even if the
      // client thinks it's still connected — `connected` reflects the
      // socket.io session state, not the underlying TCP health, and
      // after a long idle the TCP socket is usually dead while
      // socket.io's session is still 'connected' until ping-timeout.
      // disconnect()+connect() forces a fresh handshake; the connect
      // handler in socket.service.ts then rejoins all realtimeRooms and
      // fires the realtimeReconnectSubject so feed-display refetches.
      if (this.socket.realTimeSocket) {
        this.socket.realTimeSocket.disconnect();
        this.socket.realTimeSocket.connect();
      }
    } catch (err) {
      // Defensive: socket recovery should never throw, but if it does
      // we don't want to silently break the visibility-change handler
      // for the next visible event. Log and move on — the next user
      // interaction or the connectivity-status toast will surface any
      // real problem.
      console.warn('handleVisibilityChange: socket recovery failed', err);
    }
  }

  ngAfterViewInit() {
    if (location.href.includes('/viewer/')) return;
    this.fcm.initilizeFCM();
    this.storage.getUserId().then(id => {
      if (id) {
        this.socket.connect(id);
      }
    });

    try {
      if (environment.name == 'localdocker') {
        const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        if (timezone)
          this.session.setTimeZoneToLocal(timezone)
      }
    } catch (error) {
      throw new Error(`Error setting timezone: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }


  ispage(flag: string): boolean {
    if (globalThis.location.href.includes(flag)) {
      return true;
    }
    return false;
  }

  // Realtime Header Handlers
  openRtSettings() {
    this.dialog.open(RealtimesettingComponent, {
      width: '700px',
      height: 'auto',
    });
  }

  openRtAssignServers() {
    this.dialog.open(AssignserversComponent, {
      width: '700px',
      height: 'auto',
      data: 'N'
    });
  }
}
