import { Injectable } from '@angular/core';
import { initializeApp } from "firebase/app";
import { getMessaging, getToken, onMessage } from "firebase/messaging";
import { environment } from '../../../../environments/environment';
import { SecureStorageService } from '../storage/secure-storage.service';
import { NotificationsService } from '../../../shared/services/notifications.service';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { Observable, Subject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class FcmnotificationService {
  message: any
  private notificationSubject = new Subject<any>();
  constructor(public storg: SecureStorageService
    , private CMS: CommunicationService
  ) { }

  async initilizeFCM() {
    console.log('Firebase is initializing...');
    initializeApp(environment.firebase);
    // Register the service worker for Firebase messaging
    try {
      if ('serviceWorker' in navigator && 'PushManager' in window) {
        console.log('Service Worker and Push is supported');
        const registration = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
        console.log('Service Worker is registered', registration);

        await navigator.serviceWorker.ready;
        console.log('Service Worker is ready');
        // this.requestPermission();

        // Additional check for active state
        if (registration.active) {
          this.requestPermission();
        } else {
          registration.addEventListener('statechange', (e) => {
            if (registration.active) {
              this.requestPermission();
            }
          });
        }
      } else {
        console.warn('Push messaging is not supported');
      }

    } catch (error) {
      console.error('ERROR AT INITIALIZING FCM', error);
    }

    //
  }


  async requestPermission() {
    console.log('Requesting permission...');
    const messaging = getMessaging();

    try {
      const currentToken = await this.tryGetToken(messaging);
      if (currentToken) {
        this.storg.setFCMToken(currentToken);
      } else {
        console.log('No registration token available. Request permission to generate one.');
      }
    } catch (err) {
      console.error('An error occurred while retrieving token. ', err);
    }




    this.listen();
  }

  async tryGetToken(messaging, attempts = 5) {
    for (let i = 0; i < attempts; i++) {
      try {
        return await getToken(messaging, { vapidKey: environment.vapidKey });
      } catch (error) {
        console.log(`Attempt ${i + 1}: Waiting for active service worker...`);
        await new Promise(resolve => setTimeout(resolve, 1000)); // Wait for 1 second
      }
    }
    throw new Error('Max token retrieval attempts exceeded.');
  }

  listen() {
    const messaging = getMessaging();
    onMessage(messaging, (payload) => {
      this.message = payload;
      this.CMS.callFunction({ event: 'NOTIFICATION', data: this.message.data })
      this.notificationSubject.next(this.message);
    });
  }





  public onSystemNotification(): Observable<any> {
    return this.notificationSubject.asObservable();
  }

}
