import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { MatTooltipModule } from '@angular/material/tooltip';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';
import { CaseDetailResponce } from '../../../../adminpanel/interfaces/casebuilder.interface';
import { UserDetail } from '../../../models';
import { MatDialog } from '@angular/material/dialog';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { IndividualPopupComponent } from '../../../../userpanel/components/individual/individual-popup/individual-popup.component';

@Component({
  selector: 'app-realtimeheader',
  standalone: true,
  imports: [CommonModule, AvatarComponent, ButtonComponent, IconComponent, MatTooltipModule, TranslateModule],
  templateUrl: './realtimeheader.component.html',
  styleUrl: './realtimeheader.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RealtimeheaderComponent {

  @Input() currentCase: CaseDetailResponce | null = null;
  @Input() user: UserDetail | null = null;
  @Input() isOnRealtimeDashboard: boolean = false;

  @Output() exit = new EventEmitter<void>();
  @Output() openSettings = new EventEmitter<void>();
  @Output() openAssignServers = new EventEmitter<void>();

  showSettingsPopup: boolean = false;

  constructor(private dialog: MatDialog, private store: SecureStorageService) { }

  handleOpenSettings() {
    this.closeSettingsPopup();
    this.openSettings.emit();
  }

  handleOpenAssignServers() {
    this.closeSettingsPopup();
    this.openAssignServers.emit();
  }

  toggleSettingsPopup() {
    this.showSettingsPopup = !this.showSettingsPopup;
  }

  closeSettingsPopup() {
    this.showSettingsPopup = false;
  }

  handleExit() {
    let bShowAgain = this.store.getStorage('bShowAgainExitEvidence');
    if (bShowAgain == 'Y') {
      this.exit.emit();
      return;
    }

    const dialogRef = this.dialog.open(IndividualPopupComponent, {
      autoFocus: false,
      disableClose: false
    });
    dialogRef.componentInstance.isIndex = false;
    dialogRef.componentInstance.title = 'Exit Realtime';
    dialogRef.componentInstance.subTitle = 'You will exit the current realtime session';
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.exit.emit();
      }
    });
  }
}