import { CommonModule } from '@angular/common';
import { Component, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { Router } from '@angular/router';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { SearchComponent } from '../../../shared/components/search/search.component';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { HeaderService } from '../../services/header/header.service';
import { SecureStorageService } from '../../services/storage/secure-storage.service';
import { AvatarComponent } from '../../../shared/components/avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { NotificationsComponent } from '../../../shared/components/notifications/notifications.component';
import { NotificationsService } from '../../../shared/services/notifications.service';
import { SocketService } from '../../services/socket/socket.service';
import { Subscription } from 'rxjs';
import { NavigationEnd } from '@angular/router';

@Component({
  selector: 'app-mainheader',
  standalone: true,
  imports: [CommonModule, IconComponent, ProfileComponent, MatMenuModule, MatTooltipModule, NotificationsComponent,ButtonComponent],
  templateUrl: './mainheader.component.html',
  styleUrl: './mainheader.component.scss'
})
export class MainheaderComponent implements OnDestroy {
  private notifSub: Subscription | undefined;
  private routerSub: Subscription | undefined;
  private transcriptPubSub: Subscription | undefined;
  currentSection: string = 'HearingHub';

  constructor(public hs: HeaderService, public ss: SecureStorageService, public NotificationS: NotificationsService,
    private socket: SocketService, private cdr: ChangeDetectorRef, private router: Router) {

  }

  get sectionName(): string {
    return this.currentSection;
  }

  private updateSectionName(): void {
    const url = this.router.url;
    if (url.includes('/workspace')) {
      this.currentSection = 'Workspace';
    } else if (url.includes('/myfiles/factcontact')) {
      this.currentSection = 'Contacts';
    } else if (url.includes('/myfiles/task')) {
      this.currentSection = 'Task';
    } else if (url.includes('/myfiles/export')) {
      this.currentSection = 'Export';
    } else if (url.includes('/myfiles/download')) {
      this.currentSection = 'Downloads';
    } else if (url.includes('/myfiles')) {
      this.currentSection = 'Evidence';
    } else if (url.includes('/individual')) {
      this.currentSection = 'Evidence';
    } else if (url.includes('/viewer')) {
      this.currentSection = 'Evidence';
    } else if (url.includes('/marking')) {
      this.currentSection = 'Marking';
    } else if (url.includes('/realtime')) {
      this.currentSection = 'Realtime';
    } else if (url.includes('/managefiles')) {
      this.currentSection = 'Bundle';
    } else if (url.includes('/present')) {
      this.currentSection = 'Presentation';
    } else {
      this.currentSection = 'HearingHub';
    }
  }

  async ngOnInit() {
    this.hs.userdetail = await this.ss.getUserInfo();
    
    // Set initial section name
    this.updateSectionName();
    
    // Listen to route changes
    this.routerSub = this.router.events.subscribe((event) => {
      if (event instanceof NavigationEnd) {
        this.updateSectionName();
        this.cdr.detectChanges();
      }
    });
    
    // When a user notification arrives for this case, light up the red dot
    this.notifSub = this.socket.getUserNotifications().subscribe((res: any) => {
      try {
        const caseIdMatch = res?.nCaseid && (this.hs.nCaseid == res?.nCaseid || this.hs.Casedetail?.nCaseid == res?.nCaseid);
        if (caseIdMatch) {
          this.NotificationS._isNotification.next(true);
          // ensure UI updates even when backgrounded
          this.cdr.detectChanges();
        }
      } catch { }
    });

    // Transcript publish completion — surface a client-side notification
    // in the bell so users on any page (not just individual-doc) can see
    // that a final transcript is now available in Evidence > Transcript.
    this.transcriptPubSub = this.socket.getTransctipt().subscribe((res: any) => {
      if (res?.event !== 'PUBLISH-TRANSCRIPT') return;
      const data = res?.data?.data ?? res?.data;
      if (data?.status !== 'S') return;
      const nCaseid = (this.hs.nCaseid || this.hs.Casedetail?.nCaseid) as string;
      if (!nCaseid) return;
      this.NotificationS.addClientNotification({
        nNTid: 'client-ts-publish-' + Date.now(),
        cType: 'TS-PUBLISH',
        cTitle: 'Final transcript published',
        cMsg: `<strong class="block mb-1">Final transcript published</strong>The final transcript is now available in the Evidence module&apos;s Transcript folder.`,
        dDate: new Date(),
        cFname: 'System',
        cLname: '',
        cProfile: '',
        bIsseen: 'N',
        nUserid: '',
        nFSid: '',
        nDocid: '',
        nWebid: '',
        nUPid: '',
        nBundledetailid: '',
        nFBundledetailid: 0,
        nDBundledetailid: 0,
        nWBundledetailid: 0,
        cFilename: '',
        cTab: '',
        cStatus: '',
      } as any);
      this.cdr.detectChanges();
    });
  }



  gohome() {
    this.hs.goUserHome();
  }


  closenotify(ev, n: MatMenuTrigger) {
    n.closeMenu()
  }

  syncNotifcation() {
    this.NotificationS.syncNotifcation(this.hs.nCaseid);
  }

  ngOnDestroy(): void {
    try { this.notifSub?.unsubscribe(); } catch { }
    try { this.routerSub?.unsubscribe(); } catch { }
    try { this.transcriptPubSub?.unsubscribe(); } catch { }
  }


}
